update pages set contenu = '{"sections":[]}'::jsonb where path = '/secteurs/logistique/peak-season/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Peak season : préparer la logistique au pic","mecanisme":"Un compte à rebours en quatre étapes, de J-90 au bilan à froid. Revue technique chiffrée, pièces d''usure remplacées avant la vague, renforts briefés sur votre site, astreinte 24/24 et 7/7 pendant la période.","cta":"Préparer ma peak season avec Migen","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Décrivez la situation, nous vous proposons le bon dispositif."},{"type":"chiffres","chiffres":[{"valeur":"J-90","libelle":"le bon moment pour lancer la revue technique, avant les délais fournisseurs d''automne"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, astreinte 24/24 et 7/7"}]},{"type":"probleme","punchline":"Le Black Friday ne se décale pas. Votre panne, si. Elle attend décembre pour arriver.","puces":[{"accroche":"Pendant l''événement, il n''existe aucune fenêtre de réparation.","texte":"Arrêter une ligne de tri une demi-journée en pleine vague est impensable. Ce qui n''a pas été traité avant devra tenir."},{"accroche":"Les équipes élargies abîment davantage.","texte":"Nouveaux venus, cadences inhabituelles, gestes moins soigneux. Les équipements encaissent au pire moment."},{"accroche":"Chaque colis en retard devient un ticket, un avis, un remboursement de frais de port.","texte":"La satisfaction client de janvier se joue dans l''entrepôt de décembre."},{"accroche":"Les créneaux de chargement se resserrent.","texte":"Une expédition manquée se reporte sur un réseau de transport déjà saturé."},{"accroche":"Les signaux faibles passent inaperçus.","texte":"Échauffements, bourrages répétés, arrêts courts : personne ne les voit, sauf quelqu''un payé pour ça."}]}]'::jsonb) where path = '/secteurs/logistique/peak-season/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"offre","lignes":[{"prestation":{"accroche":"Revue technique complète sur site à J-90","texte":", chiffrée, équipement critique par équipement critique."},"benefice":"Vous entrez dans la vague en sachant ce qui tient et ce qui ne tient pas. Plus de découverte en décembre."},{"prestation":{"accroche":"Remplacement des pièces d''usure sensibles à J-60","texte":", réglages, constitution du stock de sécurité."},"benefice":"Les délais fournisseurs d''automne ne décident plus de votre saison."},{"prestation":{"accroche":"Renforts techniques briefés sur votre site à J-30","texte":", en horaires adaptés à votre organisation."},"benefice":"Le technicien connaît vos lignes avant le premier pic, au lieu de les découvrir pendant."},{"prestation":{"accroche":"Surveillance renforcée pendant la période","texte":"rondes ciblées, contrôles en marche, signalements traités avant la panne."},"benefice":"Les presque-pannes se traitent tant qu''elles ne coûtent que dix minutes."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7","texte":", du week-end du Black Friday aux semaines de Noël, aux mêmes conditions écrites."},"benefice":"La nuit de novembre n''attend pas le lundi matin."},{"prestation":{"accroche":"Un interlocuteur unique et des points quotidiens","texte":"avec votre responsable d''exploitation."},"benefice":"Des décisions rapides. La période ne laisse pas le temps des réunions longues."},{"prestation":{"accroche":"Bilan à froid écrit après la période","texte":"ce qui a tenu, ce qui a souffert, ce qui doit changer."},"benefice":"La préparation de l''année suivante commence avec des faits, pas avec des souvenirs."},{"prestation":{"texte":"**Dispositif prolongé sur la vague des retours de janvier.**"},"benefice":"Le second sommet est couvert, alors que la plupart des renforts sont déjà partis."},{"prestation":{"texte":"Sans préparation"},"benefice":"Avec préparation"},{"prestation":{"texte":"Pannes découvertes en pleine vague"},"benefice":"Faiblesses traitées à J-60"},{"prestation":{"texte":"Pièces critiques en rupture fournisseur"},"benefice":"Stock de sécurité constitué d''avance"},{"prestation":{"texte":"Technicien découvert dans l''urgence"},"benefice":"Renforts briefés sur site à J-30"},{"prestation":{"texte":"Arrêts subis en pleine cadence"},"benefice":"Interventions calées en heures creuses"},{"prestation":{"texte":"Urgence payée au prix fort"},"benefice":"Budget cadré, décidé à froid"},{"prestation":{"texte":"Bilan oublié dès janvier"},"benefice":"Retour d''expérience écrit, résultat mesuré"}],"prose":[{"texte":"Le dispositif s''appuie sur notre offre de [maintenance équipements logistiques](/secteurs/logistique/) et, pour le cœur du site, sur la [maintenance convoyeur](/secteurs/logistique/maintenance-convoyeur/)."}]}]'::jsonb) where path = '/secteurs/logistique/peak-season/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"deroule","etapes":[{"titre":"J-90, la revue technique","texte":"état des lieux de chaque équipement critique, convoyeurs, trieurs, quais, zones de stockage. Ce qui doit être remplacé, réglé ou surveillé. Chiffrage et prévision de pièces."},{"titre":"J-60, les travaux et les pièces","texte":"remplacement des pièces d''usure sensibles, réglages, mise en place du stock de sécurité. Le devis distingue l''indispensable du souhaitable."},{"titre":"J-30, les renforts et les procédures","texte":"techniciens briefés sur votre site, plan d''astreinte renforcé pour les nuits, consignes de premier niveau partagées avec vos équipes et vos managers."},{"titre":"Jour J, la présence","texte":"rondes techniques ciblées, interventions en heures creuses, suivi quotidien des signaux faibles, un point court chaque jour avec l''exploitation."},{"titre":"Janvier, les retours","texte":"réception et tri restent sous tension après les fêtes. Le dispositif se prolonge sur ce second sommet."},{"titre":"Le bilan","texte":"ce qui a tenu, ce qui a souffert, ce qui change avant l''année suivante. Écrit, daté, chiffré."}]},{"type":"garanties","puces":[{"accroche":"Un plan d''action daté, pas une liste de bonnes pratiques","texte":"chaque constat de la revue technique porte une échéance, un chiffrage et un responsable. Vous arbitrez sur un document, pas sur un discours."},{"accroche":"Des renforts qui connaissent le site avant le pic","texte":"briefing à J-30, sur vos lignes, avec vos consignes. 10 % des candidats retenus en entretien technique et comportemental."},{"accroche":"Une astreinte qui répond aux mêmes conditions la nuit que le jour","texte":"24/24 et 7/7 en option, mobilisation depuis le hub de techniciens le plus proche, périmètre écrit avant la période."}]},{"type":"cta","question":"Besoin d''une revue technique avant la prochaine vague ?","bouton":"Préparer ma peak season avec Migen","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Préventif tenu sur un site qui tourne 24 heures sur 24, sans fenêtre d''arrêt confortable","texte":"10 à 20 techniciens une semaine sur deux depuis septembre 2022","lienLibelle":"Étude de cas AMAZON : maintien d''un centre logistique","lienHref":"/preuves/amazon-centre-logistique/"},{"titre":"Six techniciens en permanence sur le préventif annuel de sites e-commerce","texte":"prise en charge complète réalisée en un mois","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"Maintenance curative dédiée aux convoyeurs, trieurs et packaging d''un transporteur","texte":"deux techniciens en poste sur site","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"},{"titre":"Montage d''un centre logistique en six semaines avec une date de livraison non négociable","texte":"12 monteurs, 8 engins de levage, chantier d''été","lienLibelle":"Étude de cas AKTID : montage d''un centre logistique","lienHref":"/preuves/aktid-centre-logistique/"},{"titre":"Renfort de contrôle de chantier pendant des phases critiques, automatisation logistique","texte":"intervenants intégrés aux équipes","lienLibelle":"Étude de cas ALSTEF Group : collaboration","lienHref":"/preuves/alstef-group/"}]}]'::jsonb) where path = '/secteurs/logistique/peak-season/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"objections","questions":[{"question":"Quand faut-il lancer la préparation ?","reponse":"Trois mois avant, idéalement dès octobre pour une vague de fin novembre, pour garder le temps des achats de pièces et des travaux. Un démarrage plus tardif reste utile : on hiérarchise différemment, en sécurisant d''abord les équipements dont dépend l''expédition."},{"question":"Pouvez-vous fournir des renforts seulement pour la période ?","reponse":"Oui, c''est le format le plus demandé : des techniciens briefés sur votre site avant le pic, présents pendant la période convenue, en horaires adaptés. Le dispositif s''arrête quand les volumes redescendent, sans procédure supplémentaire."},{"question":"Que couvrez-vous pendant le Black Friday et les fêtes ?","reponse":"Tout ce qui fait tenir l''entrepôt : convoyeurs, tri, quais, emballage, utilités. L''astreinte 24/24 et 7/7 couvre le week-end du Black Friday au Cyber Monday comme les semaines de Noël, aux mêmes conditions écrites qu''en semaine ordinaire."},{"question":"Travaillez-vous avec notre prestataire logistique existant ?","reponse":"Oui : nous intervenons pour le compte du logisticien comme du chargeur, en coordination avec les équipes en place. Le périmètre de chacun s''écrit avant le pic, pour que personne ne se renvoie la responsabilité pendant la vague."},{"question":"Comment gérez-vous les retours de janvier ?","reponse":"La vague des retours prolonge la charge : réception et tri restent sous tension après les fêtes, et janvier forme un second sommet. Notre dispositif se prolonge sur cette période, puis le bilan technique prépare l''année suivante."},{"question":"Que représente l''investissement ?","reponse":"La revue technique se chiffre après une visite, selon la taille du site et l''état du parc. Le devis distingue l''indispensable du souhaitable et classe les actions par priorité. Face à une seule journée d''expédition perdue, la comparaison se fait d''elle-même."}]},{"type":"ctaFinal","question":"Besoin d''entrer dans la vague en sachant ce qui va tenir ?","bouton":"Demander une revue technique avant le pic","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/secteurs/logistique/peak-season/';
